window.DICTIONARY_ENTRY_SHARDS["0075-0068"]={"0075-0068:ec4c23ea692ee2":{"word":"Uhr","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr","de-DE":"Uhr"},"forms":[{"form":"Uhr","tags":["Nominativ","Singular"]},{"form":"Uhren","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Instrument zur Messung der Zeit, Chronometer"},{"definition":"Zusatz zur Zeitangabe, zur Frage nach dem Zeitpunkt; Übersicht der Uhrzeiten im Deutschen"},{"definition":"Gerät zur Messung der Durchflussmenge, Durchströmmenge oder zur Anzeige des Flüssigkeitsstands"}],"synonyms":["Chronometer","Zeitanzeiger","Zeiteisen","Zeitmesser"],"origins":["spätmittelhochdeutsch ur(r), im 14. Jahrhundert übernommen von mittelniederdeutsch ūr(e), mittelniederländisch ure. Das niederdeutsch-niederländische Wort geht über altfranzösisch (h)ore und lateinisch hora ^(→ la) auf griechisch ὥρα (hōra^☆) ^(→ grc) „Stunde, Zeit“ zurück."],"examples":[{"text":"Ach du Schreck, meine Uhr ist stehen geblieben.","reference":""},{"text":"Wo habe ich denn meine Uhr hingelegt?","reference":""},{"text":"Die Uhr ist stehengeblieben.","reference":""},{"text":"„In einem plötzlichen Wutanfall schleuderte er die Uhr weit hinaus in das Wasser.“","reference":"Jens Rehn, Nachwort von Ursula März: Nichts in Sicht. Schöffling, Frankfurt/Main 2018, ISBN 978-3-89561-149-0, Seite 68. Erstmals 1954 erschienen."},{"text":"„In einem der Flure gab es eine alte Pendeluhr, ich glaube im ersten Stock; die Uhr stand immer; eine echte Standuhr also.“","reference":"Hansi Sondermann: Hexentotentanz und andere Kriminalgeschichten. Anthologie. Mecke Druck und Verlag, Duderstadt 2019, ISBN 978-3-86944-199-3, Seite 30 ."},{"text":"„Er sah nach der Uhr.“","reference":"Theodor Fontane: Schach von Wuthenow. Erzählung aus der Zeit des Regiments Gendarmes. Nymphenburger, München 1969, Seite 98. Entstanden 1878-82, erschienen 1882."},{"text":"„Gesundheit, Gewicht und Genuss: Wer sich richtig ernähren will, bringt die Uhr ins Spiel.“","reference":"Stefanie Kara: ZEIT Wissen; Mahl + Zeit. ZEIT Wissen Zeitverlag Gerd Bucerius GmbH & Co. KG, Hamburg 2017, Seite 49"},{"text":"Um 10 Uhr stehe ich auf.","reference":""},{"text":"Wie viel Uhr ist es?","reference":""},{"text":"Es ist kurz vor vier Uhr.","reference":""},{"text":"Es ist dreizehn Uhr dreiunddreißig Minuten.","reference":""},{"text":"„Es war bereits zwei Uhr nachmittags.“","reference":"Leo N. Tolstoi: Krieg und Frieden. Roman. Paul List Verlag, München 1971 (übersetzt von Werner Bergengruen), Seite 1173 . Russische Urfassung 1867."},{"text":"„Eine Uhr zeigt an, wie lange man noch parken darf. Fünf Minuten vor Ablauf der Zeit wird der Nutzer benachrichtigt. Dann kann man (vom Büro aus oder von unterwegs) die Parkzeit bis zur Höchstdauer erweitern.“","reference":"App statt Kleingeld: Premiere für bargeldloses Parken"},{"text":"„Eine kleine Uhr zeigt anderen Nutzern, wie lange der Platz schon frei ist. Sie müssen dann selbst abschätzen, ob es sich noch lohnt, ihn anzusteuern.“","reference":"Smarter Parken"},{"text":"„Uns dämmerte, dass wohl nicht das bereits abgeklemmte Radio oder die ebenfalls zur Vorsage abgeklemmte Uhr der Stromverbraucher an dem Van war, sondern das Standlicht, dass sich wahrscheinlich beim Tür zuschlagen irgendwie von selbst einschalten muss.“","reference":"Uhr der Stromverbraucher"},{"text":"„Berechnete Uhr des Wasserverbrauchs zur Bestimmung der Leistung der Wasseraufbereitung und der entsprechenden Ausrüstung zum Füttern des Wärmeversorgungssystems sollte genommen werden …“","reference":"Thermische Netzwerke im Freien"},{"text":"„Vergewissern Sie sich, dass der Stromausfall nicht langfristig ist. In diesem Fall fällt die Uhr des Wassererwärmers aus …“","reference":"Sinclair Wärmepumpe"},{"text":"„Neue Motoren haben einen Blowby von ca. 15 Litern/Minute. Motoren um die 300000 km stehen so bei 30 litern/Minute gemessen im Leerlauf und gegen Atmosphäre (kein Ansaugunterdruck an der Uhr).“","reference":"Blow-by"}],"idioms":["Zeit von der Uhr nehmen","rund um die Uhr","Sprichwort: in Bayern gehen die Uhren anders","Sprichwort: wer zwei Uhren hat, weiß nicht, wie spät es ist"],"collocations":[],"derivations":["Uhrarmband","Uhrenarmband","Uhrband","Uhrenaufzieher","Uhrenbauer","Uhrenfabrik","Uhrenfabrikant","Uhrenfabrikation","Uhrengehäuse","Uhrengeschäft","Uhrengewicht","Uhrenglas","Uhrenhersteller","Uhrenindustrie","Uhrenladen","Uhrenmuseum","Uhrenradio","Uhrenschlüssel","Uhrensignal","Uhrenstechkarte","Uhrenverkäufer","Uhrfeder","Uhrgehäuse","Uhrglas","Uhrkasten","Uhrenkasten","Uhrkette","Uhrmacher","Uhrpendel","Uhrschlüssel","Uhrtasche","Uhrwerk","Uhrzeiger","Uhrzeit"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Uhr","id":"ec4c23ea692ee2"},"0075-0068:a770af638d5900":{"word":"Uhu","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhu","de-DE":"Uhu"},"forms":[{"form":"Uhu","tags":["Nominativ","Singular"]},{"form":"Uhus","tags":["Nominativ","Plural"]}],"senses":[{"definition":"größte, in der Dämmerung jagende Eule, speziell der Eurasische Uhu , mit auffälligen Federohren, orangeroten Augen und dunkelbraun geflecktem Gefieder, die in waldigen Vorgebirgen lebt"},{"definition":"Universalkleber"}],"synonyms":["Eule","Nachtvogel"],"origins":["[1] seit dem 16. Jahrhundert belegt; aus dem Ostmitteldeutschen, älter ū, mittelhochdeutsch ūve, ūfe, lautmalerisch nach dem Balzruf von B. b. (Männchen ♂: tief „úo“, Weibchen ♀: höher „uhú“); neben Huhu, Schuhu, Buhu.","[2] nach dem Markennamen des Marktführers"],"examples":[{"text":"Der Uhu ist Vogel des Jahres 2005.","reference":""},{"text":"„Draußen aber heulte der Uhu sein monotones, schauriges Morgenlied, ein paar Wölfe antworteten aus weiter Ferne, und ein mattes Licht, das von dem östlichen Himmel ausging, kündeten den nahenden Morgen.“","reference":"Friedrich Gerstäcker: Die Regulatoren in Arkansas. Ein Roman aus dem amerikanischen Pflanzerleben. Fischer Taschenbuch Verlag, Frankfurt am Main 1975, Seite 155. Zuerst 1845 erschienen."},{"text":"„Er fuhr mit quietschenden Reifen davon, um den verletzten Uhu schnellstmöglich zur Tierärztin in der Wildauffangstation zu bringen, während Jean den Kopf schüttelte und französische Flüche vor sich hin murmelte.“","reference":"Elisabeth Beer: Die Bücherjägerin. Roman. 1. Auflage. DuMont, Köln 2023, ISBN 978-3-8321- 6638-0 , Seite 121."},{"text":"Reich mir bitte mal den/das Uhu rüber!","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Uhu","id":"a770af638d5900"},"0075-0068:69f9a4d4c9f4f2":{"word":"Uhudler","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhud·ler","de-DE":"Uhud·ler"},"forms":[{"form":"Uhudler","tags":["Nominativ","Singular"]},{"form":"Uhudlern","tags":["Dativ","Plural"]},{"form":"Uhudlers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Direktträgerwein aus dem Südburgenland, welcher wegen der Vernichtung europäischer Weinreben (um 1900) durch die Reblaus durch Veredelung amerikanischer, reblausresistenter Rebstöcke entwickelt wurde"}],"synonyms":[],"origins":["Die Abstammung des Namens wird volksetymologisch folgendermaßen erklärt: Nachdem der Wein hergestellt wurde und die Männer auch schon gekostet hatten und dann mit Ringen unter den Augen zu ihren Frauen kamen, sagten diese zu ihnen: \"Du schaust ja aus wie ein Uhu!\""],"examples":[{"text":"Der Uhudler war lange Zeit verboten, wird heutzutage jedoch als Spezialität gehandelt, obwohl er nicht als Qualitätswein bezeichnet werden darf.","reference":""},{"text":"Uhudler sollte gut gekühlt getrunken werden.","reference":""},{"text":"„Gott sei Dank haben sich nicht alle Weinbauern davon abhalten lassen, den Uhudler anzupflanzen. Mein Großvater war ein solcher Revolutionär. Und auch wenn er mal hat eine Strafe zahlen müssen, und seine Weinstöcke öffentlich verbrannt worden sind, der Uhudler war nicht auszurotten!","reference":"Beate Lessle-Rauter: Mord im Burgenland (Band 75 von Lindemanns Bibliothek, 2009 (Lindemanns Bibliothek), ISBN 3881905472, Seite 37"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhudler","id":"69f9a4d4c9f4f2"},"0075-0068:c1d2c105aa4ad4":{"word":"Uhrzeit","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·zeit","de-DE":"Uhr·zeit"},"forms":[{"form":"Uhrzeit","tags":["Nominativ","Singular"]},{"form":"Uhrzeiten","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Zeit, welche eine Uhr zeigt, anzeigt"}],"synonyms":["Zeit"],"origins":["Determinativkompositum, zusammengesetzt aus den Substantiven Uhr und Zeit"],"examples":[{"text":"Kannst du mir die Uhrzeit sagen?","reference":""},{"text":"„Mir wurde schlagartig bewusst, dass es in der Frauenwelt zwar durchaus praktisch ist, die Uhrzeit von einem Ziffernblatt ablesen zu können, es aber nicht unbedingt der Grund ist, eine Uhr zu tragen.“","reference":"Helge Jepsen: Frauenspielzeug. Eine beinahe vollständige Sammlung lebensnotwendiger Dinge. Hoffmann und Campe, Hamburg 2010, ISBN 978-3-455-38079-8, Seite 109."},{"text":"„Eine übergewichtige Dame mit Doppelkinn verriet, dass der Herr Kommissar um diese Uhrzeit gewöhnlich noch nicht zu nächtigen pflegte.“","reference":"Robert Baur: Blutmai. Roman. Gmeiner, Meßkirch 2018, ISBN 978-3-8392-2290-4, Seite 75."},{"text":"„Ich wusste das, weil ich jetzt zum vierten Mal um diese Uhrzeit hier oben war und er jeden Abend exakt gleich vorging.“","reference":"Jo Nesbø: Minnesota. Kriminalroman. 3. Auflage. Ullstein, Berlin 2026 (übersetzt von Günther Frauenlob), ISBN 978-3-550-20309-1, Seite 180. Norwegisch 2025."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Uhrzeit","id":"c1d2c105aa4ad4"},"0075-0068:6e06a98f104987":{"word":"Uhrmacher","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·ma·cher","de-DE":"Uhr·ma·cher"},"forms":[{"form":"Uhrmacher","tags":["Nominativ","Singular"]},{"form":"Uhrmachern","tags":["Dativ","Plural"]},{"form":"Uhrmachers","tags":["Genitiv","Singular"]},{"form":"Uhrmacherin","tags":["feminine"]}],"senses":[{"definition":"Handwerker, der sich mit der Herstellung, der Reparatur und/oder dem Verkauf von Uhren oder Uhrwerken beschäftigt"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Macher"],"examples":[{"text":"Noch heute brachte er die kaputte Uhr zum Uhrmacher.","reference":""},{"text":"„Die Uhrmacher gaben Sie alle ratlos mir zurück; Sie wollten mit solchem Teufelsstück Gar nichts zu tun zu haben.“","reference":"Wikisource-Quellentext „Meine alte Schiffsuhr“ von Joachim Ringelnatz"},{"text":"„Meist genügt es, die Uhr zum Uhrmacher seines Vertrauens zu bringen, um sie dort entmagnetisieren zu lassen.“","reference":"Endlich Ruhe zwischen den Polen. Abgerufen am 17. Januar 2019."},{"text":"„Im frühen achtzehnten Jahrhundert gab es (abgesehen von dem Autodidakten John Harrison selbst), soweit wir wissen, keinen einzigen Uhrmacher im nördlichen Lincolnshire.“","reference":"Dana Sobel; Berlin Verlag (Herausgeber): Längengrad. Die wahre Geschichte eines einsamen Genies, welches das größte wissenschaftliche Problem seiner Zeit löste. 5. Auflage. Berlin Verlag, Berlin 2005 (Originaltitel: The Illustrated Longitude, übersetzt von Matthias Fienbork, Dirk Muelder), ISBN 3-8270-0364-4, Seite 87"},{"text":"„Sein Vater war ein Uhrmacher, der sich geschickt in das Leben der alten Garnisonsstadt einordnete.“","reference":"Jürgen Serke: Die verbrannten Dichter. Lebensgeschichten und Dokumente. 2. Auflage. Wallstein, Göttingen 2023, ISBN 978-3-8353-5388-6, Seite 56."}],"idioms":[],"collocations":[],"derivations":["Uhrmacherausbildung","Uhrmacherei","Uhrmacherhandwerk","Uhrmacherkunst","Uhrmacherladen","Uhrmacherschule","Uhrmacherwerkstatt"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmacher","id":"6e06a98f104987"},"0075-0068:24620674b1f8bf":{"word":"Uhingen","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Uhin·gen","de-DE":"Uhin·gen"},"forms":[{"form":"Uhingens","tags":["Genitiv","Singular"]},{"form":"des Uhingen","tags":["Genitiv","Singular"]},{"form":"des Uhingens","tags":["Genitiv","Singular"]},{"form":"(das) Uhingen","tags":["Nominativ","Singular"]},{"form":"(dem) Uhingen","tags":["Dativ","Singular"]}],"senses":[{"definition":"eine Stadt in Baden-Württemberg, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Uhingen liegt in Deutschlands Südwesten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhingen","id":"24620674b1f8bf"},"0075-0068:6a28c8eb12e3b1":{"word":"Uhrmacherin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·ma·che·rin","de-DE":"Uhr·ma·che·rin"},"forms":[{"form":"Uhrmacher","tags":["masculine"]},{"form":"Uhrmacherin","tags":["Nominativ","Singular"]},{"form":"Uhrmacherinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Handwerkerin, die sich mit der Herstellung, der Reparatur und/oder dem Verkauf von Uhren oder Uhrwerken beschäftigt"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Uhrmacher mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"Noch heute bringt er die kaputte Uhr zur Uhrmacherin.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmacherin","id":"6a28c8eb12e3b1"},"0075-0068:47ba030ade1a58":{"word":"Uhrwerk","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uhr·werk","de-DE":"Uhr·werk"},"forms":[{"form":"Uhrwerk","tags":["Nominativ","Singular"]},{"form":"Uhrwerke","tags":["Nominativ","Plural"]},{"form":"Uhrwerks","tags":["Genitiv","Singular"]},{"form":"Uhrwerken","tags":["Dativ","Plural"]},{"form":"Uhrwerkes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"mechanisches Innenleben einer Uhr"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus Uhr und Werk"],"examples":[{"text":"Uhrwerke sollten vom Fachmann geölt und gereinigt werden.","reference":""},{"text":"[Bildunterschrift:] „Tick tack tick tack: Ein Uhrwerk läuft ziemlich konstant; […]“","reference":"Uta Steinwehr: Sommerzeit – Zeitumstellung: Stetig wie ein Uhrwerk. In: Deutsche Welle. 28. März 2021 (Bildunterschrift, URL, abgerufen am 22. Juni 2021) ."},{"text":"„Seit einigen Monaten steht das Uhrwerk der Kamenzer Turmuhr still, nun soll sie wieder laufen. Olaf Böttcher kümmert sich ehrenamtlich um das alte Uhrwerk […].“","reference":"Einfach Genial! – Hilfe für die Kamenzer Rathausuhr. In: Norddeutscher Rundfunk. 9. Mai 2021 (URL, abgerufen am 22. Juni 2021) ."},{"text":"„Seit Freitag, 28. September, bewegen sich in der Prager Altstadt die Apostelfiguren und Zeiger des historischen Uhrwerks aus dem Jahr 1410 wieder vor den Augen der Öffentlichkeit.“","reference":"Prags astronomische Uhr bewegt sich wieder. In: Deutsche Welle. 27. September 2018 (URL, abgerufen am 22. Juni 2021) ."},{"text":"„Big Ben ist bereits halb eingerüstet wegen der laufenden Sanierung des Turmgebäudes. […] Das Uhrwerk wird solange von einem modernen Elektromotor betrieben, bis der Originalmechanismus wieder eingesetzt wird.“","reference":"London ohne Big Ben-Glockenschlag. In: Deutsche Welle. 14. August 2017 (URL, abgerufen am 22. Juni 2021) ."},{"text":"[Big Ben:] „[…] auf dem vier Meter langen Pendel [liegt] ein Tablett mit alten Pennies, die man je nach Bedarf wegnehmen oder hinzufügen kann, um das Uhrwerk zu verlangsamen oder zu beschleunigen – und zwar um weniger als zwei Fünftel einer Sekunde pro Tag.“","reference":"Ruth Rach: Big Ben vor 160 Jahren – Als die Königin aller Uhren erstmals läutete. In: Deutschlandradio. 11. Juli 2019 (Deutschlandfunk Köln, Sendereihe: Kalenderblatt, URL, abgerufen am 22. Juni 2021) ."},{"text":"„Beide Uhren werden mit demselben Uhrwerk betrieben, die Herausforderung für den Uhrmacher war der Bau des Umlenkgetriebes für die zweite Uhr.“","reference":"Lieb & Teuer. In: Norddeutscher Rundfunk. 10. Oktober 2020 (URL, abgerufen am 22. Juni 2021) ."},{"text":"„Eigentlich wollte der 14-jährige Ahmed Mohamed in der Schule nur seinen selbstgebastelten Wecker präsentieren. […] Seine Lehrer hielten sein Uhrwerk fälschlicherweise für eine Bombe, was ihm prompt eine Festnahme mit großem Polizeiaufgebot einbrachte. Nun ist der Nachwuchsforscher von US-Präsident Barack Obama im Weißen Haus empfangen worden.“","reference":""}],"idioms":["wie ein Schweizer Uhrwerk"],"collocations":[],"derivations":["Uhrwerkfeder","Uhrwerkfütterer"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrwerk","id":"47ba030ade1a58"},"0075-0068:3adc319e0d251f":{"word":"Uhrzeigersinn","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·zei·ger·sinn","de-DE":"Uhr·zei·ger·sinn"},"forms":[{"form":"Uhrzeigersinn","tags":["Nominativ","Singular"]},{"form":"Uhrzeigersinne","tags":["Dativ","Singular"]},{"form":"Uhrzeigersinns","tags":["Genitiv","Singular"]},{"form":"Uhrzeigersinnes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Richtung drehender Bewegung gleich der Sonne geschuldeter Schatten, auf der Nordhalbkugel nach rechts"}],"synonyms":[],"origins":[],"examples":[{"text":"Wir können diese Position durch eine Drehung des Dreiecks um 90° im Uhrzeigersinn erreichen.","reference":""},{"text":"Bei den thermischen Ringöffnungen von Cyclobuten drehen sich die Kohlenstoffatome in die gleiche Richtung, entweder beide im oder beide gegen den Uhrzeigersinn.","reference":"Fehlender Parameter (Hilfe) Abgerufen am 10. November 2015."},{"text":"„Hantelförmig dreht sich der winkelige Kurs gegen den Uhrzeigersinn rund um die orientalisch-schöne Altstadt.“","reference":"Formel 1: Baku - die Osterweiterung der Königsklasse. Abgerufen am 2. März 2017."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrzeigersinn","id":"3adc319e0d251f"},"0075-0068:460fa0f5f5e85f":{"word":"Uhrensammlung","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uh·ren·samm·lung","de-DE":"Uh·ren·samm·lung"},"forms":[{"form":"Uhrensammlung","tags":["Nominativ","Singular"]},{"form":"Uhrensammlungen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Sammlung von Uhren"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Sammlung mit dem Fugenelement -en"],"examples":[{"text":"„Bei der Investition in Uhren spielt es grundsätzlich keine Rolle, ob man eine Uhrensammlung aufbauen oder einfach nur in Uhren investieren möchten: Die sicherste Grundlage ist die Investition in eine Uhr mit hoher Liquidität, welche man bei Bedarf schnell wieder verkaufen kann.“","reference":"wissen.de – Artikel „Diese Wertanlagen lohnen sich“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrensammlung","id":"460fa0f5f5e85f"},"0075-0068:a1dc222e95136c":{"word":"Uhrzeiger","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·zei·ger","de-DE":"Uhr·zei·ger"},"forms":[{"form":"Uhrzeiger","tags":["Nominativ","Singular"]},{"form":"Uhrzeigern","tags":["Dativ","Plural"]},{"form":"Uhrzeigers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"länglicher, beweglicher Zeiger auf dem Zifferblatt einer Uhr, an dem man die Zeit ablesen kann"}],"synonyms":[],"origins":["[1] Determinativkompositum aus den Substantiven Uhr und Zeiger"],"examples":[{"text":"„Die Uhrzeiger rückten auf sieben und weiter auf fünf nach sieben.“","reference":"Ernest Hemingway: Schnee auf dem Kilimandscharo. Storys. Rowohlt, Reinbek 2015 , Zitat Seite 114. Englische Originalausgabe Scribner, New York 1961."}],"idioms":[],"collocations":[],"derivations":["Uhrzeigerrichtung","Uhrzeigersinn"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrzeiger","id":"a1dc222e95136c"},"0075-0068:f2edfd2b81f9fc":{"word":"Uhrenmuseum","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uh·ren·mu·se·um","de-DE":"Uh·ren·mu·se·um"},"forms":[{"form":"Uhrenmuseen","tags":["Nominativ","Plural"]},{"form":"Uhrenmuseum","tags":["Nominativ","Singular"]},{"form":"Uhrenmuseums","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Einrichtung, in der Uhren und Zeitmesser aus vergangenen Zeiten ausgestellt werden"}],"synonyms":[],"origins":["Determinativkompositum aus Uhr und Museum mit dem Fugenelement -en"],"examples":[{"text":"„Die Menschen in Glashütte jedenfalls können sich die Luxusuhren von Firmen wie A. Lange & Söhne, Glashütte Original und Moritz Grossmann eher nicht leisten, wie ein Mitarbeiter des Uhrenmuseums Glashütte erzählt.“","reference":"Markus Reiter: Luxusuhren aus Glashütte: Im Innern des Uhrwerks. In: Spiegel Online. 16. Januar 2016, ISSN 0038-7452 (URL, abgerufen am 12. Juni 2016) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenmuseum","id":"f2edfd2b81f9fc"},"0075-0068:0d54185173818f":{"word":"Uhrfeder","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·fe·der","de-DE":"Uhr·fe·der"},"forms":[{"form":"Uhrfeder","tags":["Nominativ","Singular"]},{"form":"Uhrfedern","tags":["Nominativ","Plural"]}],"senses":[{"definition":"die Feder einer Uhr, die Arbeitsleistung aufnehmen und speichern kann"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Feder"],"examples":[{"text":"„Wenn die Wachsfigur die bleifarbenen Augenlider aufschlug, drang das Knistern der Uhrfeder leise durch den Kasten.“","reference":"Bloch, Ernst, Das Prinzip Hoffnung Band 1, Berlin: Aufbau-Verl. 1954, S. 393; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Uhrfeder“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrfeder","id":"0d54185173818f"},"0075-0068:87d15cd0bebee7":{"word":"Uhrenindustrie","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uh·ren·in·dus·trie","de-DE":"Uh·ren·in·dus·trie"},"forms":[{"form":"Uhrenindustrie","tags":["Nominativ","Singular"]},{"form":"Uhrenindustrien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Uhren herstellende Industrie"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Industrie mit dem Fugenelement -en"],"examples":[{"text":"„Wurde Anfang des Jahres noch auf eine Trendwende in der Uhrenindustrie gehofft, lief gerade im letzten Jahr das Geschäft mit den Luxusuhren mehr schlecht als recht […]“","reference":"Luxuskonzern Richemont: Das Uhrwerk läuft nicht rund. In: Handelsblatt Online. 12. Mai 2017, ISSN 0017-7296 (URL, abgerufen am 9. Juni 2017) ."},{"text":"„Gettler stand angeblich in Verbindung mit der Uhrenindustrie.“","reference":"Ian Fleming: Casino Royale. 3. Auflage. Heyne, München 2006, ISBN 978-3-453-50037-2, Seite 213 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenindustrie","id":"87d15cd0bebee7"},"0075-0068:3997817a30deea":{"word":"Uhrturm","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·turm","de-DE":"Uhr·turm"},"forms":[{"form":"Uhrturm","tags":["Nominativ","Singular"]},{"form":"Uhrturme","tags":["Dativ","Singular"]},{"form":"Uhrturms","tags":["Genitiv","Singular"]},{"form":"Uhrtürme","tags":["Nominativ","Plural"]},{"form":"Uhrenturm","tags":["variant"]},{"form":"Uhrturmes","tags":["Genitiv","Singular"]},{"form":"Uhrtürmen","tags":["Dativ","Plural"]}],"senses":[{"definition":"höheres Bauwerk, auf dem die Zeit angezeigt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Turm"],"examples":[{"text":"„Den Hauptturm des Fischerschlössls, der gleichzeitig Uhrturm ist, zieren kleine Türmchen an den Ecken, die Giebel der Häuser sind zinnenbekrönt.“","reference":"Kaija Voss: Ein besonderes Augenmerk auf die Gemütlichkeit. In: sueddeutsche.de. 29. August 2017, ISSN 0174-4917 (URL, abgerufen am 12. November 2017) ."},{"text":"„Der Friedhof von Akranes lag weit von der Kirche entfernt, fast am anderen Ende des Ortes, wo ein rotbrauner Uhrturm zum Himmel zeigte.“","reference":"Eva Björg Ægisdóttir: Verschwiegen. Ein Island-Krimi. 1. Auflage. Kiepenheuer & Witsch, Köln 2024 (übersetzt von Freyja Melsted), ISBN 978-3-462-00663-6, Seite 125. Isländisch 2018."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrturm","id":"3997817a30deea"},"0075-0068:c1e3dd46db49b5":{"word":"Uhrenturm","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uh·ren·turm","de-DE":"Uh·ren·turm"},"forms":[{"form":"Uhrturm","tags":["variant"]},{"form":"Uhrenturm","tags":["Nominativ","Singular"]},{"form":"Uhrenturme","tags":["Dativ","Singular"]},{"form":"Uhrenturms","tags":["Genitiv","Singular"]},{"form":"Uhrentürme","tags":["Nominativ","Plural"]},{"form":"Uhrenturmes","tags":["Genitiv","Singular"]},{"form":"Uhrentürmen","tags":["Dativ","Plural"]}],"senses":[{"definition":"höheres Bauwerk, auf dem die Zeit angezeigt wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Turm mit dem Fugenelement -en"],"examples":[{"text":"„Der neunstöckige Uhrenturm deutet wohl an, dass die Hofanlage eine Stadt in der Stadt sein könnte, wie sie dem Namensgeber, Bürgermeister Karl Seitz, durchaus zugestanden wäre.“","reference":"Christoph Mandl: Wiener Wohn-Sinn. tredition, Hamburg 2016 (Zitiert nach Google Books)"},{"text":"„Dann fuhren sie durch das üppige Susquehannatal und sahen die Kuppeln und Dächer und den Uhrenturm des Campus, das ganze amerikanische, nicht jüdische Kleinstadtambiente, bürgerlich und republikanisch, aber unprätentiös und einladend.“","reference":"Blake Bailey: Philip Roth. Biografie. Hanser, München 2023 (übersetzt von Dirk van Gunsteren, Thomas Gunkel), ISBN 978-3-446-27612-3, Seite 96. Englisch 2021 erschienen."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenturm","id":"c1e3dd46db49b5"},"0075-0068:ae3ea3647cf0b7":{"word":"Uhrmacherei","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·ma·che·rei","de-DE":"Uhr·ma·che·rei"},"forms":[{"form":"Uhrmacherei","tags":["Nominativ","Singular"]},{"form":"Uhrmachereien","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Handwerk, durch das Uhren hergestellt oder repariert werden"},{"definition":"die Werkstatt des Uhrmachers"}],"synonyms":[],"origins":[],"examples":[{"text":"„Uhrmacherei, zumal in der Schweiz, hat mit Handwerk und Tradition zu tun.“","reference":"Die Zeit, 02.04.2008, Nr. 15; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Uhrmacherei“"},{"text":"„Uhrmachereien sind häufig Familienbetriebe, in denen die Fertigkeit von Generation zu Generation weitergegeben wird.“","reference":"Süddeutsche Zeitung, 15.01.1998; zitiert nach: Digitales Wörterbuch der deutschen Sprache „Uhrmacherei“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmacherei","id":"ae3ea3647cf0b7"},"0075-0068:6f4625d119aab8":{"word":"Uhrmacherladen","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·mach·er·la·den","de-DE":"Uhr·mach·er·la·den"},"forms":[{"form":"Uhrmacherladen","tags":["Nominativ","Singular"]},{"form":"Uhrmacherläden","tags":["Nominativ","Plural"]},{"form":"Uhrmacherladens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Geschäft eines Uhrmachers"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhrmacher und Laden"],"examples":[{"text":"„Unterwegs sahen wir eine weinende Frau vor einem Uhrmacherladen und eine Gruppe von Forsyths Männern nahebei.“","reference":"James Fenimore Cooper: Ned oder Ein Leben vor dem Mast. 3. Auflage. mareverlag, Hamburg 2017 (übersetzt von Alexander Pechmann), ISBN 978-3-86648-190-9 , Seite 99. Englisches Original 1843."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmacherladen","id":"6f4625d119aab8"},"0075-0068:784b61fa91e039":{"word":"Uhrmachermeister","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·ma·cher·meis·ter","de-DE":"Uhr·ma·cher·meis·ter"},"forms":[{"form":"Uhrmachermeister","tags":["Nominativ","Singular"]},{"form":"Uhrmachermeistern","tags":["Dativ","Plural"]},{"form":"Uhrmachermeisters","tags":["Genitiv","Singular"]},{"form":"Uhrmachermeisterin","tags":["feminine"]}],"senses":[{"definition":"Person, die den Meistertitel im Uhrmacherhandwerk hat"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhrmacher und Meister"],"examples":[{"text":"„Ihr Vater, Herbert Schöning, arbeitete als Uhrmachermeister bei Juwelier Franzen in Monschau.“","reference":"Mechtild Borrmann: Grenzgänger. Die Geschichte einer verlorenen deutschen Kindheit. Roman. Droemer, München 2019, ISBN 978-3-426-30608-6, Seite 19."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmachermeister","id":"784b61fa91e039"},"0075-0068:96a89a62fe6b9a":{"word":"Uhrmachermeisterin","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·ma·cher·meis·te·rin","de-DE":"Uhr·ma·cher·meis·te·rin"},"forms":[{"form":"Uhrmachermeister","tags":["masculine"]},{"form":"Uhrmachermeisterin","tags":["Nominativ","Singular"]},{"form":"Uhrmachermeisterinnen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"weibliche Person, die den Meistertitel im Uhrmacherhandwerk hat"}],"synonyms":[],"origins":["Ableitung (Motion, Movierung) des Femininums aus der männlichen Form Uhrmachermeister mit dem Derivatem (Ableitungsmorphem) -in"],"examples":[{"text":"„Dabei hatten geladene Clubmitglieder unter Anleitung der Uhrmachermeisterin Romana Ressl getreu dem Motto „When a watch comes to life“ Gelegenheit, selbst ein Uhrwerk zusammenzubauen.“","reference":"Uhrenjournal: Branchenticker. Abgerufen am 11. Oktober 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmachermeisterin","id":"96a89a62fe6b9a"},"0075-0068:35dfe91a639d09":{"word":"Uhrpendel","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uhr·pen·del","de-DE":"Uhr·pen·del"},"forms":[{"form":"Uhrpendel","tags":["Nominativ","Singular"]},{"form":"Uhrpendeln","tags":["Dativ","Plural"]},{"form":"Uhrpendels","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Pendel in einer Uhr"}],"synonyms":["Perpendikel"],"origins":["Determinativkompositum aus den Substantiven Uhr und Pendel"],"examples":[{"text":"„Wieder entstand eine Pause, wieder nur das sanfte Tektektek des schwingenden Uhrpendels.“","reference":"Mechtild Borrmann: Grenzgänger. Die Geschichte einer verlorenen deutschen Kindheit. Roman. Droemer, München 2019, ISBN 978-3-426-30608-6, Seite 240."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Uhrpendel","id":"35dfe91a639d09"},"0075-0068:799a3bd76b4b48":{"word":"uh","partOfSpeech":"Interjektion","gender":"","hyphenation":{"de-CH":"uh","de-DE":"uh"},"forms":[],"senses":[{"definition":"Ausruf des Widerwillens, des Erschreckens"}],"synonyms":[],"origins":[],"examples":[{"text":"Uh, was für ein Scheißwetter.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"uh","id":"799a3bd76b4b48"},"0075-0068:1677ea1d3bde63":{"word":"Uhrtasche","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·ta·sche","de-DE":"Uhr·ta·sche"},"forms":[{"form":"Uhrtasche","tags":["Nominativ","Singular"]},{"form":"Uhrtaschen","tags":["Nominativ","Plural"]},{"form":"Uhrentasche","tags":["variant"]}],"senses":[{"definition":"kleine Tasche an/in einem Kleidungsstück für eine Uhr"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Tasche"],"examples":[{"text":"„Ich erwiderte, es sei an der Uhrtasche festgenäht, und das entsprach der Wahrheit.“","reference":"Giacomo Casanova: Geschichte meines Lebens, herausgegeben und eingeleitet von Erich Loos, Band 1. Propyläen, Berlin 1985 (Neuausgabe) (übersetzt von Heinz von Sauter), Seite 238."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrtasche","id":"1677ea1d3bde63"},"0075-0068:eab4de0c68f8d8":{"word":"Uhrkasten","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·kas·ten","de-DE":"Uhr·kas·ten"},"forms":[{"form":"Uhrkasten","tags":["Nominativ","Singular"]},{"form":"Uhrkästen","tags":["Nominativ","Plural"]},{"form":"Uhrkastens","tags":["Genitiv","Singular"]},{"form":"Uhrenkasten","tags":["variant"]}],"senses":[{"definition":"schützendes Gehäuse um das Uhrwerk (eventuell auch Pendel und Gewichte) einer größeren Uhr"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Kasten"],"examples":[{"text":"Im Märchen „Der Wolf und die sieben Geißlein“ schafft es ein Geißlein, sich vor dem Wolf im Uhrkasten einer Standuhr zu verstecken.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrkasten","id":"eab4de0c68f8d8"},"0075-0068:a35db7a3d343e2":{"word":"Uhrenkasten","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uh·ren·kas·ten","de-DE":"Uh·ren·kas·ten"},"forms":[{"form":"Uhrkasten","tags":["variant"]},{"form":"Uhrenkasten","tags":["Nominativ","Singular"]},{"form":"Uhrenkästen","tags":["Nominativ","Plural"]},{"form":"Uhrenkastens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"schützendes Gehäuse um das Uhrwerk (eventuell auch Pendel und Gewichte) einer größeren Uhr"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Kasten mit dem Fugenelement -en"],"examples":[{"text":"„Die Notenständer, während der Woche in einem alten Uhrenkasten geborgen, werden hervorgeholt und in der Stube aufgestellt.“","reference":"Karl Schönherr: Allerhand Kreuzköpf. In: Projekt Gutenberg-DE. (URL, abgerufen am 1. Juli 2022) . Alte Version im Internet-Archiv abrufbar. *"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenkasten","id":"a35db7a3d343e2"},"0075-0068:7bc3f4dccf2d93":{"word":"Uhrenradio","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uh·ren·ra·dio","de-DE":"Uh·ren·ra·dio"},"forms":[{"form":"Uhrenradio","tags":["Nominativ","Singular"]},{"form":"Uhrenradios","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Gerät, das sowohl eine Uhr als auch ein Radio enthält und als Wecker fungiert"}],"synonyms":["Radiowecker"],"origins":["Determinativkompositum aus Uhr und Radio mit dem Fugenelement -en"],"examples":[{"text":"Mein Uhrenradio zeigt immer die falsche Uhrzeit an.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Uhrenradio","id":"7bc3f4dccf2d93"},"0075-0068:a47f8dc164443b":{"word":"Uhrenladen","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uh·ren·la·den","de-DE":"Uh·ren·la·den"},"forms":[{"form":"Uhrenladen","tags":["Nominativ","Singular"]},{"form":"Uhrenläden","tags":["Nominativ","Plural"]},{"form":"Uhrenladens","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Geschäft, in dem Uhren verkauft werden"}],"synonyms":[],"origins":["Determinativkompositum aus Uhr und Laden mit dem Fugenelement -en"],"examples":[],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenladen","id":"a47f8dc164443b"},"0075-0068:12a85d84af7143":{"word":"Uhrenhersteller","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uh·ren·her·stel·ler","de-DE":"Uh·ren·her·stel·ler"},"forms":[{"form":"Uhrenhersteller","tags":["Nominativ","Singular"]},{"form":"Uhrenherstellern","tags":["Dativ","Plural"]},{"form":"Uhrenherstellers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Unternehmen, das Uhren produziert; das Uhren entwickelt, baut und verkauft"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Hersteller sowie dem Fugenelement -en"],"examples":[{"text":"„Neben Rolex gehören auch andere namhafte Schweizer Uhrenhersteller von der Haute Horlogerie abwärts zum Kundenstock von Böhler Edelstahl, das zu den weltweit bedeutendsten Anbietern von Schnellarbeitsstahl, Werkzeugstahl sowie Sonderwerkstoffen zählt.“","reference":"Markus Böhm: Hidden Champions: Österreichs Beitrag zur Welt der Luxusuhren. In: Der Standard digital. 21. April 2016 (URL, abgerufen am 14. Dezember 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenhersteller","id":"12a85d84af7143"},"0075-0068:d2922ffae33e8e":{"word":"Uhrkette","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Uhr·ket·te","de-DE":"Uhr·ket·te"},"forms":[{"form":"Uhrkette","tags":["Nominativ","Singular"]},{"form":"Uhrketten","tags":["Nominativ","Plural"]},{"form":"Uhrenkette","tags":["alternative"]}],"senses":[{"definition":"Kette, an der man eine Uhr gesichert mit sich führen kann"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Kette"],"examples":[{"text":"„Schwarz-grau gestreifte Hosen mit messerscharfen Bügelfalten trug der Herr, eine zweireihige schwarze kurze Jacke, eine schwarze Weste mit goldener Uhrkette, ein weißes Hemd mit hohem, steifem Kragen, eine perlgraue Krawatte.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 35. Erstveröffentlichung Zürich 1960."},{"text":"„Seine Uhrkette aus Haaren und die Art, wie er die Remoularde rührte, offenbarte den erfahrenen Lebemann, und er aß, den Zipfel seiner Serviette unter die Achsel geklemmt, und ließ dabei allerhand Witze vom Stapel, die Pécuchet zum Lachen brachten.“","reference":"Gustave Flaubert: Bouvard und Pécuchet. Roman. Diogenes, Zürich 1979 (übersetzt von Erich Marx), ISBN 3-257-20725-5 , Seite 13. Französisch 1881."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrkette","id":"d2922ffae33e8e"},"0075-0068:d0ec30b2c7e22d":{"word":"Uhrband","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uhr·band","de-DE":"Uhr·band"},"forms":[{"form":"Uhrband","tags":["Nominativ","Singular"]},{"form":"Uhrbande","tags":["Dativ","Singular"]},{"form":"Uhrbands","tags":["Genitiv","Singular"]},{"form":"Uhrbandes","tags":["Genitiv","Singular"]},{"form":"Uhrbänder","tags":["Nominativ","Plural"]},{"form":"Uhrbändern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Armband für eine Uhr"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Band"],"examples":[{"text":"„Der Juwelier legte Fred Meyer am unteren Ende des Ladentisches eine Reihe von Uhrbändern vor.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 344. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrband","id":"d0ec30b2c7e22d"},"0075-0068:428c96478b0024":{"word":"Uhrenarmband","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uh·ren·arm·band","de-DE":"Uh·ren·arm·band"},"forms":[{"form":"Uhrarmband","tags":["variant"]},{"form":"Uhrenarmband","tags":["Nominativ","Singular"]},{"form":"Uhrenarmbande","tags":["Dativ","Singular"]},{"form":"Uhrenarmbands","tags":["Genitiv","Singular"]},{"form":"Uhrenarmbandes","tags":["Genitiv","Singular"]},{"form":"Uhrenarmbänder","tags":["Nominativ","Plural"]},{"form":"Uhrenarmbändern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Armband für eine Uhr"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Armband sowie dem Fugenelement -en"],"examples":[{"text":"„Auf dieses vereinbarte Zeichen hin entschloß sich Fred Meyer ungemein rasch zum Erwerb eines Uhrenarmbandes im Wert von 240 Franc.“","reference":"Johannes Mario Simmel: Es muß nicht immer Kaviar sein. Mit auserlesenen Kochrezepten des Geheimagenten wider Willen. Nikol, Hamburg 2015, ISBN 978-3-86820-292-2, Seite 344. Erstveröffentlichung Zürich 1960."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrenarmband","id":"428c96478b0024"},"0075-0068:fcdfe468f18d0b":{"word":"Uhrglas","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uhr·glas","de-DE":"Uhr·glas"},"forms":[{"form":"Uhrglas","tags":["Nominativ","Singular"]},{"form":"Uhrglase","tags":["Dativ","Singular"]},{"form":"Uhrenglas","tags":["variant"]},{"form":"Uhrglases","tags":["Genitiv","Singular"]},{"form":"Uhrgläser","tags":["Nominativ","Plural"]},{"form":"Uhrgläsern","tags":["Dativ","Plural"]}],"senses":[{"definition":"Schutzglas über dem Ziffernblatt und den Zeigern einer Uhr"},{"definition":"(an Bedeutung 1 erinnerndes) flaches, rundes, meist leicht gewölbtes Glasgefäß, das in Laboren verwendet wird"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Glas"],"examples":[{"text":"„Beim Polo ging so manche herkömmliche Uhr kaputt, weil der harte Ball das Uhrglas zerstörte.“","reference":"Andreas Kurtz: Ein offener Salon. In: Berliner Zeitung, 23. August 2002 (zitiert nach DWDS)."},{"text":"„Für das Experiment wird ein Tropfen Quecksilber in ein Uhrglas gegeben und mit einem Elektrolyten wie Schwefelsäure, das ein Oxidationsmittel wie Wasserstoffperoxid, Kaliumpermanganat oder Kaliumdichromat enthält, überschichtet.“","reference":"Wikipedia-Artikel „Schlagendes Quecksilberherz“ (Stabilversion), abgerufen am 31. Mai 2025."}],"idioms":[],"collocations":[],"derivations":["Uhrglasnagel"],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrglas","id":"fcdfe468f18d0b"},"0075-0068:163a968b6f0525":{"word":"Uhrengeschäft","partOfSpeech":"Substantiv","gender":"das","hyphenation":{"de-CH":"Uh·ren·ge·schäft","de-DE":"Uh·ren·ge·schäft"},"forms":[{"form":"Uhrgeschäft","tags":["variant"]},{"form":"Uhrengeschäft","tags":["Nominativ","Singular"]},{"form":"Uhrengeschäfte","tags":["Nominativ","Plural"]},{"form":"Uhrengeschäfts","tags":["Genitiv","Singular"]},{"form":"Uhrengeschäften","tags":["Dativ","Plural"]},{"form":"Uhrengeschäftes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Geschäft, in dem Uhren verkauft werden"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhr und Geschäft mit dem Fugenelement -en"],"examples":[{"text":"„Ein als Frau verkleideter Räuber soll mit zwei Komplizen ein Uhrengeschäft in Berlin überfallen haben.“","reference":"Berlin: Uhren-Räuber hatte sich als Frau verkleidet - Fahndung. In: Spiegel Online. 1. November 2022, ISSN 0038-7452 (URL, abgerufen am 31. August 2024) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrengeschäft","id":"163a968b6f0525"},"0075-0068:743eb30e809833":{"word":"Uhrmacherlehrling","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Uhr·mach·er·lehr·ling","de-DE":"Uhr·mach·er·lehr·ling"},"forms":[{"form":"Uhrmacherlehrling","tags":["Nominativ","Singular"]},{"form":"Uhrmacherlehrlinge","tags":["Nominativ","Plural"]},{"form":"Uhrmacherlehrlings","tags":["Genitiv","Singular"]},{"form":"Uhrmacherlehrlingen","tags":["Dativ","Plural"]}],"senses":[{"definition":"Lehrling, der eine Ausbildung zum Uhrmacher absolviert"}],"synonyms":[],"origins":["Determinativkompositum aus den Substantiven Uhrmacher und Lehrling"],"examples":[{"text":"„Begonnen hatte Celentanos Karriere in den fünfziger Jahren, als der Sohn apulischer Gastarbeiter, der Schulabbrecher und Uhrmacherlehrling in einem Mailänder Kino den amerikanischen Rock'n'Roll kennen lernte.“","reference":"Adriano Celentano: „Azzurro“ für immer. Abgerufen am 8. Dezember 2024."},{"text":"„Er lernt in einer der besten Uhrenmanufakturen und will wie sein Vorbild Giulio Papi Grossmeister werden: Nicolas Huguenin, Uhrmacherlehrling bei Audemars Piguet in Le Locle.“","reference":"Der Zeigerlehrling. Abgerufen am 8. Dezember 2024."},{"text":"„Den Durchbruch zum Kino-Erfolg schaffte der 45jährige ehemalige Uhrmacherlehrling aus der Via Gluck in Mailands Armenviertel erst im zweiten Anlauf.“","reference":"Zucker vom Affen. Abgerufen am 8. Dezember 2024."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhrmacherlehrling","id":"743eb30e809833"},"0075-0068:0091f8bde36ef4":{"word":"Uhlmann","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Uh·l·mann","de-DE":"Uh·l·mann"},"forms":[{"form":"U.","tags":["Kurzform"]},{"form":"Ulman","tags":["alternative"]},{"form":"Uhlman","tags":["alternative"]},{"form":"Ullman","tags":["variant"]},{"form":"Ulmann","tags":["alternative"]},{"form":"Uhleman","tags":["variant"]},{"form":"Uhlmann","tags":["Nominativ","Singular","masculine"]},{"form":"Ulemann","tags":["variant"]},{"form":"Ullmann","tags":["variant"]},{"form":"Uhlemann","tags":["variant"]},{"form":"Uhlmanns","tags":["Genitiv","Singular","masculine"]},{"form":"dem Uhlmann","tags":["Dativ","Singular","masculine"]},{"form":"den Uhlmann","tags":["Akkusativ","Singular","masculine"]},{"form":"der Uhlmann","tags":["Nominativ","Singular","masculine"]},{"form":"des Uhlmann","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhlmann","tags":["Nominativ","Singular","feminine"]},{"form":"den Uhlmanns","tags":["Dativ","Plural"]},{"form":"der Uhlmanns","tags":["Genitiv","Plural"]},{"form":"des Uhlmanns","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhlmanns","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Uhlmann ist ein Genie im Verkauf.","reference":""},{"text":"Herr Uhlmann wollte uns kein Interview geben.","reference":""},{"text":"Die Uhlmanns fliegen heute nach La Paz.","reference":""},{"text":"Der Uhlmann trägt nie die Schals, die die Uhlmann ihm strickt.","reference":""},{"text":"Das kann ich dir aber sagen: „Wenn die Frau Uhlmann kommt, geht der Herr Uhlmann.“","reference":""},{"text":"Uhlmann kommt und geht.","reference":""},{"text":"Uhlmanns kamen, sahen und siegten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhlmann","id":"0091f8bde36ef4"},"0075-0068:9cc587345ef0c5":{"word":"Uhlemann","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Uh·le·mann","de-DE":"Uh·le·mann"},"forms":[{"form":"U.","tags":["Kurzform"]},{"form":"Ulman","tags":["variant"]},{"form":"Uhlman","tags":["variant"]},{"form":"Ullman","tags":["variant"]},{"form":"Ulmann","tags":["variant"]},{"form":"Uhleman","tags":["alternative"]},{"form":"Ulemann","tags":["alternative"]},{"form":"Ullmann","tags":["variant"]},{"form":"Uhlemann","tags":["Nominativ","Singular","masculine"]},{"form":"Uehlemann","tags":["alternative"]},{"form":"Uhlemanns","tags":["Genitiv","Singular","masculine"]},{"form":"dem Uhlemann","tags":["Dativ","Singular","masculine"]},{"form":"den Uhlemann","tags":["Akkusativ","Singular","masculine"]},{"form":"der Uhlemann","tags":["Nominativ","Singular","masculine"]},{"form":"des Uhlemann","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhlemann","tags":["Nominativ","Singular","feminine"]},{"form":"den Uhlemanns","tags":["Dativ","Plural"]},{"form":"der Uhlemanns","tags":["Genitiv","Plural"]},{"form":"des Uhlemanns","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhlemanns","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Uhlemann ist ein Genie im Verkauf.","reference":""},{"text":"Herr Uhlemann wollte uns kein Interview geben.","reference":""},{"text":"Die Uhlemanns fliegen heute nach La Paz.","reference":""},{"text":"Der Uhlemann trägt nie die Schals, die die Uhlemann ihm strickt.","reference":""},{"text":"Das kann ich dir aber sagen: „Wenn die Frau Uhlemann kommt, geht der Herr Uhlemann.“","reference":""},{"text":"Uhlemann kommt und geht.","reference":""},{"text":"Uhlemanns kamen, sahen und siegten.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhlemann","id":"9cc587345ef0c5"},"0075-0068:9b694b9e7ae53b":{"word":"Uhlenhorst","partOfSpeech":"Toponym","gender":"das","hyphenation":{"de-CH":"Uh·len·horst","de-DE":"Uh·len·horst"},"forms":[{"form":"Uhlenhorsts","tags":["Genitiv","Singular"]},{"form":"des Uhlenhorst","tags":["Genitiv","Singular"]},{"form":"des Uhlenhorsts","tags":["Genitiv","Singular"]},{"form":"(das) Uhlenhorst","tags":["Nominativ","Singular"]},{"form":"(dem) Uhlenhorst","tags":["Dativ","Singular"]},{"form":"Uhlenhorst","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Ortsteil von Damnatz in Niedersachsen, Deutschland"},{"definition":"Ortsteil von Dänischenhagen, Schleswig-Holstein, Deutschland"},{"definition":"Wohnplatz von Mühlenbecker Land, Brandenburg, Deutschland"},{"definition":"Wohnplatz von Leezen, Mecklenburg-Vorpommern, Deutschland"},{"definition":"Ortslage in Köpenick, Berlin, Deutschland"},{"definition":"Ansiedlung in der Region Hardap, Namibia"},{"definition":"früherer Name des Ortes Lipki im Oblast Kaliningrad, Russland"},{"definition":"Stadtteil von Hamburg, Deutschland"}],"synonyms":[],"origins":[],"examples":[{"text":"Uhlenhorst liegt im Landkreis Lüchow-Dannenberg.","reference":""},{"text":"Uhlenhorst liegt in Deutschlands Norden.","reference":""},{"text":"Uhlenhorst liegt in Deutschlands Osten.","reference":""},{"text":"Uhlenhorst liegt in Deutschlands Nordosten.","reference":""},{"text":"Uhlenhorst liegt in Namibias Zentrum.","reference":""},{"text":"Der früher Uhlenhorst genannte Ort Lipki liegt in der russischen Exklave Kaliningrad.","reference":""},{"text":"Ich wohne auf der Uhlenhorst.","reference":""},{"text":"Ein Finanzmakler auf der Uhlenhorst ist verhaftet worden, weil er Anlagebetrug in Millionenhöhe verursacht haben soll.","reference":"Betrugsverdacht: Durchsuchung bei Finanzmakler. In: Norddeutscher Rundfunk. 22. Juli 2015 (URL, abgerufen am 18. August 2025) ."},{"text":"„Es habe vereinzelt Hinweise gegeben, dass Kinder auf der Uhlenhorst von sogenannten „Mitschnackern“ angesprochen wurden.“","reference":"Tessa Mallon: Mitschnacker auf der Uhlenhorst? Eltern fordern mehr Schutz auf Spielplätzen. In: Hamburger Morgenpost. Morgenpost Verlag GmbH, 27. Juli 2025, abgerufen am 5. April 2026 (HTTPS)."},{"text":"„Wusstet ihr, dass man auf der Uhlenhorst Stand-Up-Paddling als Unterrichtsfach wählen kann?“","reference":"Isabell Wüppenhorst: Stand-up-Paddling als Unterrichtsfach auf der Uhlenhorst? In: Radio Hamburg. Radio Hamburg GmbH & Co. KG, 15. Mai 2025, abgerufen am 5. April 2026 (HTTPS)."},{"text":"„Der Asphalt wird erneuert, über eine lange Strecke ist die Straße auf der Uhlenhorst gesperrt.“","reference":"Melanie Wassink: Sperrung von zentraler Straße nahe Alster sorgt für Einschränkungen. In: Hamburger Abendblatt Online. ISSN 0949-4618 (URL, abgerufen am 18. August 2025) ."},{"text":"„Groß geworden ist sie auf der Uhlenhorst, zwischen Außenalster und Kuhmühlenteich.“","reference":"Friederike Oertel: Zufällig Pionierin. Geboren ist sie auf der Uhlenhorst, schon ihr Urgroßvater ruderte. In: Zeit Online. 8. Juli 2020, ISSN 0044-2070 (Seite 2/4, URL, abgerufen am 18. August 2025) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhlenhorst","id":"9b694b9e7ae53b"},"0075-0068:0ac2da800cd469":{"word":"Uhse","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Uhse","de-DE":"Uhse"},"forms":[{"form":"U.","tags":["Kurzform"]},{"form":"Uhse","tags":["Nominativ","Singular","masculine"]},{"form":"Uhses","tags":["Genitiv","Singular","masculine"]},{"form":"dem Uhse","tags":["Dativ","Singular","masculine"]},{"form":"den Uhse","tags":["Dativ","Plural"]},{"form":"der Uhse","tags":["Nominativ","Singular","masculine"]},{"form":"des Uhse","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhse","tags":["Nominativ","Singular","feminine"]},{"form":"den Uhses","tags":["Dativ","Plural"]},{"form":"der Uhses","tags":["Genitiv","Plural"]},{"form":"des Uhses","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhses","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Uhse arbeitet als Schifffahrtskauffrau.","reference":""},{"text":"Herr Uhse ist im Verein tätig.","reference":""},{"text":"Die Uhses fahren heute nach Jüterbog.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhse","id":"0ac2da800cd469"},"0075-0068:1f64fcf696d6e6":{"word":"Uhle","partOfSpeech":"Nachname","gender":"die","hyphenation":{"de-CH":"Uhle","de-DE":"Uhle"},"forms":[{"form":"U.","tags":["Kurzform"]},{"form":"Uhl","tags":["variant"]},{"form":"Uhle","tags":["Nominativ","Singular","masculine"]},{"form":"Ühle","tags":["variant"]},{"form":"Uehle","tags":["variant"]},{"form":"Uhles","tags":["Genitiv","Singular","masculine"]},{"form":"dem Uhle","tags":["Dativ","Singular","masculine"]},{"form":"den Uhle","tags":["Dativ","Plural"]},{"form":"der Uhle","tags":["Nominativ","Singular","masculine"]},{"form":"des Uhle","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhle","tags":["Nominativ","Singular","feminine"]},{"form":"den Uhles","tags":["Dativ","Plural"]},{"form":"der Uhles","tags":["Genitiv","Plural"]},{"form":"des Uhles","tags":["Genitiv","Singular","masculine"]},{"form":"die Uhles","tags":["Nominativ","Plural"]}],"senses":[{"definition":"deutschsprachiger Nachname, Familienname"}],"synonyms":[],"origins":[],"examples":[{"text":"Frau Uhle arbeitet als Snowboardlehrerin.","reference":""},{"text":"Herr Uhle spielt gerne Schafkopf.","reference":""},{"text":"Die Uhles fahren heute nach Aschersleben.","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Uhle","id":"1f64fcf696d6e6"}};
